<script setup>
import { ref,computed,watch,onBeforeUnmount } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { api,notify,speak,refresh } from '../api'
import Icon from '../components/Icon.vue'
import '../sentences.css'
const route=useRoute(),router=useRouter()
const validTraining=['study','recall','response']
const training=ref(validTraining.includes(route.query.training)?route.query.training:'study')
const queueMode=ref(route.query.mode||'mixed'),level=ref(route.query.level!==undefined?route.query.level:'basic'),limit=ref(5)
const queue=ref([]),position=ref(0),step=ref(0),recalled=ref(false),replyShown=ref(false),questionShown=ref(false)
const loading=ref(true),busy=ref(false),error=ref(''),eventId=ref(''),retryRating=ref(''),info=ref(null),loaded=ref(false),lastDue=ref('')
const current=computed(()=>queue.value[position.value]),complete=computed(()=>loaded.value && queue.value.length>0 && !current.value)
const title=computed(()=>({study:'Nghe & hiểu trong ngữ cảnh',recall:'Tự nhớ câu',response:'Luyện phản xạ đáp lại'}[training.value]))
const stages=[['Headphones','Nghe trước'],['BookOpen','Hiểu câu'],['RotateCw','Tự nhớ'],['MessagesSquare','Đáp lại']]
const ratings=[['again','Chưa nhớ','10 phút'],['hard','Còn khó','Ôn sớm hơn'],['good','Đã nhớ','1 · 3 · 7 · 14 ngày'],['easy','Rất dễ','Giãn lịch ôn']]
let generation=0
function resetCard(){step.value=training.value==='study'?0:training.value==='recall'?2:3;recalled.value=false;replyShown.value=false;questionShown.value=false;eventId.value=crypto.randomUUID();retryRating.value='';lastDue.value=''}
async function load(){const version=++generation;loading.value=true;error.value='';try{const params=new URLSearchParams({mode:queueMode.value,level:level.value,limit:limit.value});if(route.query.lesson)params.set('lesson',route.query.lesson);if(route.query.sentence)params.set('sentence_id',route.query.sentence);const result=await api('/sentences/queue?'+params);if(version===generation){queue.value=result.items;info.value=result;position.value=0;resetCard();loaded.value=true}}catch(e){if(version===generation)error.value=e.message}finally{if(version===generation)loading.value=false}}
async function rate(rating){if(!current.value||busy.value||(retryRating.value && retryRating.value!==rating))return;busy.value=true;error.value='';try{const result=await api('/sentences/review',{method:'POST',body:JSON.stringify({sentence_id:current.value.id,event_id:eventId.value,rating,mode:training.value})});position.value++;resetCard();lastDue.value=new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(result.due_at));refresh().catch(e=>notify(e.message))}catch(e){error.value=e.message;retryRating.value=rating}finally{busy.value=false}}
function changeOptions(){router.replace({path:'/sentences/learn',query:{...route.query,training:training.value,mode:queueMode.value,level:level.value}});if('speechSynthesis' in window)window.speechSynthesis.cancel()}
watch([queueMode,level],changeOptions)
watch(training,()=>{if(busy.value)return;resetCard();router.replace({path:'/sentences/learn',query:{...route.query,training:training.value}})})
watch(limit,load)
watch(()=>[route.query.mode,route.query.level,route.query.lesson,route.query.sentence],()=>{queueMode.value=route.query.mode||'mixed';level.value=route.query.level!==undefined?route.query.level:'basic';load()})
onBeforeUnmount(()=>{generation++;if('speechSynthesis' in window)window.speechSynthesis.cancel()})
load()
</script>
<template><div class="page sentence-study-page"><div class="page-heading"><div><RouterLink to="/sentences" class="text-link sentence-back"><Icon name="ChevronLeft" :size="15"/>900 câu giao tiếp</RouterLink><h1>{{title}}</h1><p>{{route.query.lesson ? `Buổi ${route.query.lesson} · ` : ''}}Thử nói thành tiếng trước khi mở câu tham khảo.</p></div><RouterLink to="/sentences?tab=progress" class="btn outline">Xem tiến độ<Icon name="ArrowUpRight" :size="16"/></RouterLink></div>
<div class="sentence-learning-controls"><label>Cách luyện<select v-model="training" :disabled="busy||loading"><option value="study">Nghe, hiểu & đáp lại</option><option value="recall">Tự nhớ câu</option><option value="response">Phản xạ đáp lại</option></select></label><label v-if="!['lesson','single'].includes(queueMode)">Chọn câu<select v-model="queueMode" :disabled="busy||loading"><option value="mixed">Ôn đến hạn + học mới</option><option value="due">Chỉ câu đến hạn</option><option value="new">Chỉ câu mới</option><option value="saved">Các câu đã lưu</option></select></label><label v-if="!['lesson','single'].includes(queueMode)">Trình độ<select v-model="level" :disabled="busy||loading"><option value="basic">A1–A2 · Khởi đầu</option><option value="">Mọi trình độ</option><option>A1</option><option>A2</option><option>B1</option><option>B2</option><option>C1</option></select></label><label v-if="queueMode!=='single'">Câu mới / lượt<select v-model.number="limit" :disabled="busy||loading"><option :value="5">5 câu</option><option :value="10">10 câu</option></select></label></div>
<div v-if="loading" class="loading-panel">Đang chuẩn bị lượt luyện…</div><div v-else-if="error&&!current" class="error-panel" role="alert">{{error}}<button class="btn outline" @click="load">Thử lại</button></div>
<section v-else-if="complete" class="session-complete"><div class="complete-icon"><Icon name="PartyPopper" :size="42"/></div><div class="eyebrow">MỘT CHÚT NÓI ĐƯỢC THÊM</div><h2>Đã luyện {{queue.length}} câu giao tiếp</h2><p>Lịch ôn đã được lưu riêng cho từng câu. Hãy thử dùng một câu vừa học trong cuộc sống hôm nay.</p><p v-if="lastDue" class="sentence-last-due">Câu vừa rồi được hẹn ôn: {{lastDue}}</p><div class="heading-actions"><RouterLink to="/sentences?tab=progress" class="btn primary">Xem tiến độ<Icon name="ArrowRight" :size="17"/></RouterLink><button class="btn outline" @click="load">{{queueMode==='lesson' ? 'Học tiếp / luyện lại buổi' : 'Kiểm tra lượt tiếp theo'}}</button></div></section>
<section v-else-if="!current" class="session-complete"><div class="complete-icon"><Icon name="CircleCheck" :size="40"/></div><h2>{{info?.new_remaining===0 && queueMode!=='due' ? 'Đã đủ câu mới cho hôm nay' : 'Chưa có câu phù hợp trong lượt này'}}</h2><p>{{queueMode==='saved' ? 'Lưu câu trong Kho câu để tạo bộ câu riêng.' : 'Bạn có thể chọn trình độ khác, ôn câu đã lưu hoặc học chủ động theo buổi.'}}</p><p v-if="info?.due_remaining" class="muted">Còn {{info.due_remaining}} câu đến hạn; hãy ưu tiên ôn trước khi học mới.</p><div class="heading-actions"><RouterLink to="/sentences?tab=lessons" class="btn primary">Chọn buổi học</RouterLink><RouterLink to="/sentences?tab=library" class="btn outline">Khám phá kho câu</RouterLink></div></section>
<div v-else class="sentence-workspace"><div class="study-progress"><span>CÂU {{position+1}} / {{queue.length}}</span><span>{{current.id}} · Buổi {{current.lesson}} · {{current.level}}</span><div class="progress-track"><span :style="{width:position/queue.length*100+'%'}"></span></div></div><div v-if="training==='study'" class="sentence-steps"><span v-for="([icon,label],i) in stages" :key="label" :class="{active:step===i,done:step>i}"><Icon :name="step>i?'Check':icon" :size="16"/>{{label}}</span></div>
<section class="sentence-learning-card"><div class="sentence-scene"><span><Icon name="MapPin" :size="15"/>{{current.situation}}</span><span>{{current.context}} · {{current.topic}}</span></div>
<div v-if="step===0" class="sentence-stage listen-stage"><div class="eyebrow">NGHE TRƯỚC KHI XEM CHỮ</div><button class="big-audio" aria-label="Nghe câu giao tiếp" @click="speak(current.english)"><Icon name="Volume2" :size="38"/></button><h2>Bạn nghe được những gì?</h2><p>Nghe 1–2 lần. Thử đoán ý từ tình huống ở trên.</p><button class="text-link" @click="speak(current.english,.65)">Nghe chậm hơn</button><button class="btn primary full" @click="step=1">Xem câu & nghĩa<Icon name="ArrowRight" :size="17"/></button></div>
<div v-else-if="step===1" class="sentence-stage understand-stage"><div class="eyebrow">HIỂU CÂU TRONG TÌNH HUỐNG</div><h2>{{current.english}}</h2><p class="sentence-stage-meaning">{{current.vietnamese}}</p><div class="sentence-audio-actions"><button class="audio-button" @click="speak(current.english)"><Icon name="Volume2" :size="19"/>Nghe & nói theo</button><button class="audio-button" @click="speak(current.english,.65)">Nghe chậm</button></div><div class="sentence-instruction"><Icon name="MessagesSquare" :size="23"/><p>Thử nói theo cả câu. Sau đó nghĩ đến một lần bạn có thể dùng câu này.</p></div><button class="btn primary full" @click="step=2">Ẩn câu để tự nhớ<Icon name="RotateCw" :size="17"/></button></div>
<div v-else-if="step===2" class="sentence-stage recall-stage"><div class="eyebrow">TỰ NÓI TIẾNG ANH TRƯỚC KHI XEM</div><h2 class="recall-meaning">{{current.vietnamese}}</h2><p class="sentence-stage-hint">Bạn sẽ nói câu này bằng tiếng Anh thế nào?</p><template v-if="recalled"><div class="sentence-reference"><span>CÂU TRONG BỘ HỌC</span><p>{{current.english}}</p><button class="audio-button" @click="speak(current.english)"><Icon name="Volume2" :size="18"/>Nghe để đối chiếu</button></div><p class="sentence-alternatives">Bạn có thể diễn đạt khác nếu vẫn đúng ý và phù hợp tình huống.</p><button v-if="training==='study'" class="btn primary full" @click="step=3">Luyện đáp lại<Icon name="MessagesSquare" :size="17"/></button></template><button v-else class="btn primary full" @click="recalled=true">Xem câu để đối chiếu<Icon name="ArrowRight" :size="17"/></button></div>
<div v-else class="sentence-stage response-stage"><div class="eyebrow">NGƯỜI ĐỐI DIỆN NÓI…</div><button class="big-audio compact" aria-label="Nghe lời người đối diện" @click="speak(current.english)"><Icon name="Volume2" :size="28"/></button><div v-if="questionShown || training==='study'" class="conversation-prompt"><h2>{{current.english}}</h2><p>{{current.vietnamese}}</p></div><button v-else class="text-link" @click="questionShown=true">Hiện lời người đối diện</button><p class="sentence-stage-hint">Thử đáp lại thành tiếng theo cách của bạn.</p><div v-if="replyShown" class="sentence-reference reply-reference"><span>MỘT CÁCH ĐÁP LẠI</span><p>{{current.reply_english}}</p><small>{{current.reply_vietnamese}}</small><button class="audio-button" @click="speak(current.reply_english)"><Icon name="Volume2" :size="18"/>Nghe câu đáp</button></div><button v-else class="btn primary full" @click="replyShown=true">Xem gợi ý đáp lại<Icon name="MessagesSquare" :size="17"/></button><p v-if="replyShown" class="sentence-alternatives">Đây là gợi ý tham khảo. Nhiều cách trả lời khác cũng có thể phù hợp.</p></div>
</section>
<template v-if="(step===2 && recalled && training==='recall') || (step===3 && replyShown)"><div class="sentence-rating-intro"><h3>{{training==='response'?'Bạn tự đáp lại được đến đâu?':'Bạn tự nhớ được đến đâu?'}}</h3><p>Tự đánh giá để app hẹn lần ôn tiếp theo.</p></div><div class="rating-grid sentence-ratings"><button v-for="[rating,label,hint] in ratings" :key="rating" :class="['rating-button',rating]" :disabled="busy || (!!retryRating && retryRating!==rating)" @click="rate(rating)"><strong>{{retryRating===rating?'Thử lưu lại':label}}</strong><small>{{hint}}</small></button></div></template>
<p v-if="error" class="form-error centered" role="alert">{{error}} · Nhấn “Thử lưu lại” để lưu lượt này.</p><p class="sentence-session-note">Tiến độ lưu sau mỗi lần đánh giá. Bạn có thể dừng và quay lại sau.</p></div>
</div></template>
